#!/usr/bin/env node
/**
 * TRED — la relance du soir, et la revision sur le telephone.
 *
 *     node <chemin>\tred-relance.mjs
 *
 * LE TROU QU'ELLE BOUCHE
 *
 * La repetition espacee etait complete sauf sur un point : elle ecrivait des
 * rendez-vous que personne ne tenait. Aucune tache planifiee, nulle part.
 * L'etudiant n'apprenait qu'une revision etait due qu'en ouvrant TRED de
 * lui-meme -- ce qui vide de son sens l'idee meme d'espacer.
 *
 * CE QUI ARRIVE
 *
 *   Serveur
 *     - lib/evening-reminder.ts : une boucle dans le processus, reveillee tous
 *       les quarts d'heure, qui n'agit qu'a 19 h heure de Berlin. Intl gere le
 *       passage a l'heure d'hiver -- verifie sur les deux saisons.
 *     - table `job_run` : un VERROU, pas un historique. UPDATE conditionnel
 *       atomique : sur deux repliques Railway, une seule envoie.
 *     - textes en de / en / fr, choisis d'apres la langue enregistree cote
 *       serveur -- la seule connue quand l'application n'est pas ouverte.
 *     - envoi en serie, pas en parallele : 500 notifications d'un coup
 *       saturent la sortie et font expirer les requetes des etudiants qui,
 *       eux, sont en train de s'en servir.
 *
 *   Mobile
 *     - app/review.tsx : la revision, une lacune a la fois, deux boutons.
 *       SANS CET ECRAN la notification aurait ouvert une app incapable de
 *       montrer ce qu'elle annonce -- on derange, et on ne sert a rien.
 *     - une banniere sur l'accueil quand il y a des lacunes dues, pour que ca
 *       existe aussi sans notification.
 *     - l'aiguillage des notifications est corrige : `screen` inconnu menait
 *       vers `/(tabs)/<rien>` et laissait un ecran d'erreur d'expo-router.
 *
 *   Menage
 *     - notifyQuotaReached retiree : ecrite, jamais appelee, et a juste titre.
 *       Une notification poussee pour annoncer un plafond arrive pendant que
 *       l'etudiant lit deja l'erreur a l'ecran.
 *
 * POUR L'ARRETER : variable DISABLE_EVENING_REMINDER=true sur Railway.
 */
import { writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

function racine() {
  const departs = [process.cwd(), dirname(fileURLToPath(import.meta.url))];
  for (const depart of departs) {
    let d = depart;
    for (let i = 0; i < 8; i++) {
      if (existsSync(join(d, "packages", "web", "package.json"))) return d;
      const p = dirname(d);
      if (p === d) break;
      d = p;
    }
  }
  return null;
}

const ROOT = racine();
if (!ROOT) {
  console.error("\n  x  Depot introuvable.\n");
  process.exit(1);
}

const FILES = {
"packages/web/src/api/database/schema.ts": "",
"packages/web/src/api/index.ts": "",
"packages/web/src/api/lib/push.ts": "",
"packages/web/src/api/lib/evening-reminder.ts": "",
"packages/mobile/app/_layout.tsx": "",
"packages/mobile/app/review.tsx": "",
"packages/mobile/app/(tabs)/index.tsx": "",
"packages/mobile/hooks/use-notifications.ts": "",
"packages/mobile/queries/memory.ts": "",
"packages/mobile/i18n/de.ts": "",
"packages/mobile/i18n/en.ts": "",
"packages/mobile/i18n/fr.ts": ""
};
for (const [rel, b64] of Object.entries(FILES)) {
  const cible = join(ROOT, rel);
  mkdirSync(dirname(cible), { recursive: true });
  writeFileSync(cible, Buffer.from(b64, "base64"));
  console.log("  ecrit  " + rel);
}

console.log(`
  ETAPE OBLIGATOIRE :

      node migre-base.mjs

  La table job_run est neuve. Sans elle, la boucle echoue chaque quart
  d'heure dans les journaux -- sans casser le serveur, mais sans rien
  envoyer non plus.

  La relance ne partira que ce soir a 19 h, heure de Berlin, et seulement
  vers des etudiants qui ont l'app installee ET des lacunes dues. Pour la
  voir tourner tout de suite, il faut des donnees : ouvre le chat, laisse
  le tuteur noter une lacune, puis regarde les journaux Railway a 19 h.
`);
